  let tmp_2 = rocq_array::set::<u64>(tmp_1, 0u64, 0u64);
  let A = items_1(g, n, m, 0u64, tmp_2);
  let tmp_3 = rocq_array::get::<u64>(&A, mod_(k, m));
  std::mem::drop(A);
  leb(tmp_3, k)
